def count_vowels(string):
    vowels = ['a','e','i','o','u','A','E','I','O','U']
    count = 0
    for character in string:
        if character in vowels:
            count += 1
        elif character == 'y' and string.index(character) == len(string) - 1:
            count += 1
        elif character == 'Y' and string.index(character) == len(string) - 1:
            count += 1
    return count

import re

def extract_script_vars(html_content):
    script_vars = {}
    script_var_pattern = r"var (\w+) = '(.*?)';"
    lines = html_content.split('\n')

    for line in lines:
        match = re.search(script_var_pattern, line)
        if match:
            var_name = match.group(1)
            var_value = match.group(2)
            script_vars[var_name] = var_value

    return script_vars

def extract_hidden_fields(html_content):
    hidden_fields = {}
    hidden_field_pattern = r'<input type="hidden" name="(.*)" value="(.*)".*/>'
    lines = html_content.split('\n')

    for line in lines:
        match = re.search(hidden_field_pattern, line)
        if match:
            field_name = match.group(1)
            field_value = match.group(2)
            hidden_fields[field_name] = field_value

    return hidden_fields

def get_search_params(html_content):
    script_vars = extract_script_vars(html_content)
    hidden_fields = extract_hidden_fields(html_content)

    params = []
    params.append(('j_token', script_vars['j_token']))
    params.append(('v_token', script_vars['v_token']))

    for field, value in hidden_fields.items():
        params.append((field, value))

    return params

