    infected_hijacked = []

    for host in alive_hosts:
        open_ports = nm[host]['tcp'].keys()
        for port in open_ports:
            service_name = nm[host]['tcp'][port]['name']
            if 'ssh' in service_name.lower():
                os.system('ssh root@' + host)
            if 'ftp' in service_name.lower():
                os.system('ftp anonymous@' + host)

