    max_price = None

    if obj['low'] is not None:
        min_price = float(obj['low'])

    if obj['high'] is not None:
        max_price = float(obj['high'])

    return min_price, max_price

def analyze_sales_results(sales):
    sales_count = 0
    total_sales = Fraction(0)

    for sale in sales:
        min_price, max_price = get_range(sale['price'])

        if min_price is None:
            min_price = 0
        if max_price is None:
            max_price = 0

        average_sale_price = (min_price + max_price) / 2

        total_sales = total_sales + Fraction(average_sale_price)
        sales_count += 1

    average_sales = total_sales / len(sales)
    return float(average_sales)

