    if element == 'Sodium':
        return 'Na(s) + 2 H2O(l) → Na+ (aq) + 2 HO- (aq)'
    elif element == 'Magnesium':
        return 'Mg(s) + 2 H2O(l) → Mg2+ (aq) + 2 HO- (aq)'

def generate_precipitation_reaction(metal_cation, anion):
    return f'{metal_cation}2+ (aq) + {anion}2- (aq) → {metal_cation}{anion}(s)'

